'use strict';

/**
 * High-Performance Linear-Light HDR 2D SDF & Vector Renderer
 * Uses Float32Array linear RGB accumulation buffer with filmic tone mapping
 * and anti-aliased Signed Distance Field (SDF) primitives.
 */

class HDRCanvas {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.buf = new Float32Array(width * height * 3);
    this.out = new Uint8Array(width * height * 3);

    // Precompute sRGB lookup table for fast linear -> sRGB conversion
    this.lutSize = 4096;
    this.srgbLut = new Uint8Array(this.lutSize);
    for (let i = 0; i < this.lutSize; i++) {
      // Filmic curve + gamma 2.2
      const x = (i / (this.lutSize - 1)) * 2.5; // map [0, 2.5] HDR range
      // ACES-like filmic curve
      const a = 2.51, b = 0.03, c = 2.43, d = 0.59, e = 0.14;
      const mapped = Math.min(1.0, Math.max(0.0, (x * (a * x + b)) / (x * (c * x + d) + e)));
      const srgb = Math.pow(mapped, 1.0 / 2.2);
      this.srgbLut[i] = Math.min(255, Math.max(0, Math.round(srgb * 255)));
    }
  }

  clear(r, g, b) {
    const buf = this.buf;
    const n = buf.length;
    for (let i = 0; i < n; i += 3) {
      buf[i] = r;
      buf[i + 1] = g;
      buf[i + 2] = b;
    }
  }

  /**
   * Render rich vertical + radial atmospheric background
   */
  drawBackground(topRGB, bottomRGB, centerGlowRGB, glowX, glowY, glowRadius) {
    const { width, height, buf } = this;
    const invH = 1.0 / height;
    const invR2 = 1.0 / (glowRadius * glowRadius);

    let idx = 0;
    for (let y = 0; y < height; y++) {
      const ty = y * invH;
      const br = topRGB[0] + (bottomRGB[0] - topRGB[0]) * ty;
      const bg = topRGB[1] + (bottomRGB[1] - topRGB[1]) * ty;
      const bb = topRGB[2] + (bottomRGB[2] - topRGB[2]) * ty;
      const dy2 = (y - glowY) * (y - glowY);

      for (let x = 0; x < width; x++) {
        const dx = x - glowX;
        const d2 = (dx * dx + dy2) * invR2;
        const g = Math.exp(-d2 * 1.5);
        buf[idx] = br + centerGlowRGB[0] * g;
        buf[idx + 1] = bg + centerGlowRGB[1] * g;
        buf[idx + 2] = bb + centerGlowRGB[2] * g;
        idx += 3;
      }
    }
  }

  /**
   * Blend a pixel at (x, y) in linear space.
   * mode = 'alpha' (standard over) or 'add' (HDR additive glow)
   */
  blendPixel(x, y, r, g, b, alpha, additive = 0.0) {
    if (alpha <= 0.0005) return;
    const idx = (y * this.width + x) * 3;
    const buf = this.buf;
    const invA = 1.0 - alpha * (1.0 - additive);
    buf[idx] = buf[idx] * invA + r * alpha;
    buf[idx + 1] = buf[idx + 1] * invA + g * alpha;
    buf[idx + 2] = buf[idx + 2] * invA + b * alpha;
  }

  /**
   * Anti-aliased SDF Circle (filled and/or stroked, with optional HDR glow)
   */
  drawCircle(cx, cy, radius, color, alpha = 1.0, glowRadius = 0.0, glowIntensity = 0.5, additive = 0.0) {
    const { width, height, buf } = this;
    const pad = Math.ceil(radius + glowRadius + 2);
    const x0 = Math.max(0, Math.floor(cx - pad));
    const x1 = Math.min(width - 1, Math.ceil(cx + pad));
    const y0 = Math.max(0, Math.floor(cy - pad));
    const y1 = Math.min(height - 1, Math.ceil(cy + pad));

    const [cr, cg, cb] = color;
    const hasGlow = glowRadius > 0.5;
    const invGlow = hasGlow ? 1.0 / glowRadius : 0;

    for (let y = y0; y <= y1; y++) {
      const dy = y - cy;
      const dy2 = dy * dy;
      let rowIdx = (y * width + x0) * 3;
      for (let x = x0; x <= x1; x++) {
        const dx = x - cx;
        const dist = Math.sqrt(dx * dx + dy2) - radius;

        let a = 0.0;
        let isAdd = additive;
        if (dist <= 0.75) {
          // Smooth anti-aliased edge
          const core = dist < -0.75 ? 1.0 : (0.75 - dist) / 1.5;
          a = core * alpha;
        }
        if (hasGlow && dist > -glowRadius && dist < glowRadius) {
          const gd = Math.max(0, dist) * invGlow;
          const g = Math.exp(-gd * gd * 3.5) * glowIntensity * alpha;
          a = Math.min(1.0, a + g);
          if (dist > 0.75) isAdd = 1.0;
        }

        if (a > 0.001) {
          const invA = 1.0 - a * (1.0 - isAdd);
          buf[rowIdx] = buf[rowIdx] * invA + cr * a;
          buf[rowIdx + 1] = buf[rowIdx + 1] * invA + cg * a;
          buf[rowIdx + 2] = buf[rowIdx + 2] * invA + cb * a;
        }
        rowIdx += 3;
      }
    }
  }

  /**
   * Anti-aliased Ring / Arc (supports partial startAngle..endAngle in radians)
   */
  drawArc(cx, cy, radius, thickness, startAngle, endAngle, color, alpha = 1.0, glowRadius = 0.0, additive = 0.0) {
    const { width, height, buf } = this;
    const halfT = thickness * 0.5;
    const pad = Math.ceil(radius + halfT + glowRadius + 3);
    const x0 = Math.max(0, Math.floor(cx - pad));
    const x1 = Math.min(width - 1, Math.ceil(cx + pad));
    const y0 = Math.max(0, Math.floor(cy - pad));
    const y1 = Math.min(height - 1, Math.ceil(cy + pad));

    const [cr, cg, cb] = color;
    const fullCircle = (endAngle - startAngle) >= Math.PI * 1.999;
    const midAngle = 0.5 * (startAngle + endAngle);
    const halfSpan = 0.5 * (endAngle - startAngle);
    const cosMid = Math.cos(midAngle);
    const sinMid = Math.sin(midAngle);
    const capX1 = cx + Math.cos(startAngle) * radius;
    const capY1 = cy + Math.sin(startAngle) * radius;
    const capX2 = cx + Math.cos(endAngle) * radius;
    const capY2 = cy + Math.sin(endAngle) * radius;

    const hasGlow = glowRadius > 0.5;
    const invGlow = hasGlow ? 1.0 / glowRadius : 0;

    for (let y = y0; y <= y1; y++) {
      const dy = y - cy;
      let rowIdx = (y * width + x0) * 3;
      for (let x = x0; x <= x1; x++) {
        const dx = x - cx;
        const r = Math.sqrt(dx * dx + dy * dy);
        // Quick radial reject
        const radialDist = Math.abs(r - radius) - halfT;
        if (radialDist > glowRadius + 1.5) {
          rowIdx += 3;
          continue;
        }

        let sdf = radialDist;
        if (!fullCircle && r > 0.001) {
          // Check if angle is within [startAngle, endAngle]
          // Dot product with midAngle vector
          const ux = dx / r;
          const uy = dy / r;
          const dot = ux * cosMid + uy * sinMid;
          const angDist = Math.acos(Math.min(1.0, Math.max(-1.0, dot)));
          if (angDist > halfSpan) {
            // Distance to rounded endpoints
            const d1 = Math.hypot(x - capX1, y - capY1) - halfT;
            const d2 = Math.hypot(x - capX2, y - capY2) - halfT;
            sdf = Math.min(d1, d2);
          }
        }

        let a = 0.0;
        let isAdd = additive;
        if (sdf <= 0.75) {
          const core = sdf < -0.75 ? 1.0 : (0.75 - sdf) / 1.5;
          a = core * alpha;
        }
        if (hasGlow && sdf < glowRadius) {
          const gd = Math.max(0, sdf) * invGlow;
          const g = Math.exp(-gd * gd * 3.5) * 0.55 * alpha;
          a = Math.min(1.0, a + g);
          if (sdf > 0.75) isAdd = 1.0;
        }

        if (a > 0.001) {
          const invA = 1.0 - a * (1.0 - isAdd);
          buf[rowIdx] = buf[rowIdx] * invA + cr * a;
          buf[rowIdx + 1] = buf[rowIdx + 1] * invA + cg * a;
          buf[rowIdx + 2] = buf[rowIdx + 2] * invA + cb * a;
        }
        rowIdx += 3;
      }
    }
  }

  /**
   * Anti-aliased Tapered Capsule (line from (ax, ay) with radius rA to (bx, by) with radius rB)
   * Great for limbs, torso segments, bronchioles, lightning, and typography strokes.
   */
  drawCapsule(ax, ay, bx, by, rA, rB, color, alpha = 1.0, glowRadius = 0.0, additive = 0.0) {
    const { width, height, buf } = this;
    const maxR = Math.max(rA, rB) + glowRadius + 2;
    const x0 = Math.max(0, Math.floor(Math.min(ax, bx) - maxR));
    const x1 = Math.min(width - 1, Math.ceil(Math.max(ax, bx) + maxR));
    const y0 = Math.max(0, Math.floor(Math.min(ay, by) - maxR));
    const y1 = Math.min(height - 1, Math.ceil(Math.max(ay, by) + maxR));

    const vx = bx - ax;
    const vy = by - ay;
    const len2 = vx * vx + vy * vy;
    const invLen2 = len2 > 1e-6 ? 1.0 / len2 : 0.0;
    const [cr, cg, cb] = color;
    const hasGlow = glowRadius > 0.5;
    const invGlow = hasGlow ? 1.0 / glowRadius : 0;

    for (let y = y0; y <= y1; y++) {
      const wy = y - ay;
      let rowIdx = (y * width + x0) * 3;
      for (let x = x0; x <= x1; x++) {
        const wx = x - ax;
        const t = Math.min(1.0, Math.max(0.0, (wx * vx + wy * vy) * invLen2));
        const px = ax + t * vx;
        const py = ay + t * vy;
        const r = rA + (rB - rA) * t;
        const sdf = Math.hypot(x - px, y - py) - r;

        if (sdf > glowRadius + 0.8) {
          rowIdx += 3;
          continue;
        }

        let a = 0.0;
        let isAdd = additive;
        if (sdf <= 0.75) {
          const core = sdf < -0.75 ? 1.0 : (0.75 - sdf) / 1.5;
          a = core * alpha;
        }
        if (hasGlow && sdf < glowRadius) {
          const gd = Math.max(0, sdf) * invGlow;
          const g = Math.exp(-gd * gd * 3.5) * 0.5 * alpha;
          a = Math.min(1.0, a + g);
          if (sdf > 0.75) isAdd = 1.0;
        }

        if (a > 0.001) {
          const invA = 1.0 - a * (1.0 - isAdd);
          buf[rowIdx] = buf[rowIdx] * invA + cr * a;
          buf[rowIdx + 1] = buf[rowIdx + 1] * invA + cg * a;
          buf[rowIdx + 2] = buf[rowIdx + 2] * invA + cb * a;
        }
        rowIdx += 3;
      }
    }
  }

  /**
   * Draw smooth polyline / spline with tapered radius or constant radius
   */
  drawPath(points, radiusFn, color, alpha = 1.0, glowRadius = 0.0, additive = 0.0) {
    const n = points.length;
    if (n < 2) return;
    for (let i = 0; i < n - 1; i++) {
      const t0 = i / (n - 1);
      const t1 = (i + 1) / (n - 1);
      const r0 = typeof radiusFn === 'function' ? radiusFn(t0, i) : radiusFn;
      const r1 = typeof radiusFn === 'function' ? radiusFn(t1, i + 1) : radiusFn;
      this.drawCapsule(
        points[i][0], points[i][1],
        points[i + 1][0], points[i + 1][1],
        r0, r1, color, alpha, glowRadius, additive
      );
    }
  }

  /**
   * Draw anti-aliased filled polygon (with optional soft feather edge)
   */
  drawPolygon(pts, color, alpha = 1.0, feather = 1.2, additive = 0.0) {
    const { width, height, buf } = this;
    const n = pts.length;
    if (n < 3) return;

    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    for (let i = 0; i < n; i++) {
      const [px, py] = pts[i];
      if (px < minX) minX = px;
      if (px > maxX) maxX = px;
      if (py < minY) minY = py;
      if (py > maxY) maxY = py;
    }

    const pad = Math.ceil(feather + 2);
    const x0 = Math.max(0, Math.floor(minX - pad));
    const x1 = Math.min(width - 1, Math.ceil(maxX + pad));
    const y0 = Math.max(0, Math.floor(minY - pad));
    const y1 = Math.min(height - 1, Math.ceil(maxY + pad));

    const [cr, cg, cb] = color;
    const invFeather = 1.0 / Math.max(0.5, feather);

    for (let y = y0; y <= y1; y++) {
      let rowIdx = (y * width + x0) * 3;
      for (let x = x0; x <= x1; x++) {
        // Compute signed distance to polygon
        let inside = false;
        let minDist2 = Infinity;

        for (let i = 0, j = n - 1; i < n; j = i++) {
          const xi = pts[i][0], yi = pts[i][1];
          const xj = pts[j][0], yj = pts[j][1];

          const intersect = ((yi > y) !== (yj > y)) &&
            (x < (xj - xi) * (y - yi) / (yj - yi + 1e-12) + xi);
          if (intersect) inside = !inside;

          const vx = xj - xi, vy = yj - yi;
          const l2 = vx * vx + vy * vy;
          const t = l2 > 1e-6 ? Math.min(1.0, Math.max(0.0, ((x - xi) * vx + (y - yi) * vy) / l2)) : 0.0;
          const dx = x - (xi + t * vx);
          const dy = y - (yi + t * vy);
          const d2 = dx * dx + dy * dy;
          if (d2 < minDist2) minDist2 = d2;
        }

        const sdf = (inside ? -1.0 : 1.0) * Math.sqrt(minDist2);
        if (sdf < feather) {
          const cov = Math.min(1.0, Math.max(0.0, 0.5 - sdf * invFeather));
          const a = cov * alpha;
          if (a > 0.001) {
            const invA = 1.0 - a * (1.0 - additive);
            buf[rowIdx] = buf[rowIdx] * invA + cr * a;
            buf[rowIdx + 1] = buf[rowIdx + 1] * invA + cg * a;
            buf[rowIdx + 2] = buf[rowIdx + 2] * invA + cb * a;
          }
        }
        rowIdx += 3;
      }
    }
  }

  /**
   * Convert HDR float buffer to 8-bit sRGB Uint8Array with subtle vignette and dither
   */
  toSRGB() {
    const { width, height, buf, out, srgbLut, lutSize } = this;
    const scale = (lutSize - 1) / 2.5;
    const cx = width * 0.5;
    const cy = height * 0.5;
    const invMaxR2 = 1.0 / (cx * cx + cy * cy);

    let idx = 0;
    for (let y = 0; y < height; y++) {
      const dy2 = (y - cy) * (y - cy);
      for (let x = 0; x < width; x++) {
        const dx = x - cx;
        // Subtle cinematic vignette (max 18% darkening at extreme corners)
        const vig = 1.0 - 0.18 * ((dx * dx + dy2) * invMaxR2);
        // Tiny hash dither to prevent 8-bit gradient banding
        const dither = (((x * 13 + y * 37) & 7) - 3.5) * 0.0005;

        const r = Math.max(0, (buf[idx] * vig + dither) * scale);
        const g = Math.max(0, (buf[idx + 1] * vig + dither) * scale);
        const b = Math.max(0, (buf[idx + 2] * vig + dither) * scale);

        out[idx] = srgbLut[Math.min(lutSize - 1, r | 0)];
        out[idx + 1] = srgbLut[Math.min(lutSize - 1, g | 0)];
        out[idx + 2] = srgbLut[Math.min(lutSize - 1, b | 0)];
        idx += 3;
      }
    }
    return out;
  }
}

module.exports = { HDRCanvas };

'use strict';

/**
 * Articulated Human Figure & Inner Physiology (Lungs, Bronchi, Alveoli, Vagus Nerve, Heart)
 * Renders expressive, volumetric layered silhouettes with anatomical inner light.
 */

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function lerpColor(c1, c2, t) {
  return [
    lerp(c1[0], c2[0], t),
    lerp(c1[1], c2[1], t),
    lerp(c1[2], c2[2], t)
  ];
}

/**
 * Draw an organic glowing heart shape at (cx, cy) with scale r
 */
function drawHeartOrgan(canvas, cx, cy, r, color, alpha = 1.0, glow = 12.0) {
  canvas.drawCircle(cx - r * 0.28, cy - r * 0.18, r * 0.55, color, alpha, glow, 0.7, 0.5);
  canvas.drawCircle(cx + r * 0.28, cy - r * 0.18, r * 0.55, color, alpha, glow, 0.7, 0.5);
  canvas.drawCapsule(cx - r * 0.35, cy - r * 0.05, cx, cy + r * 0.68, r * 0.48, r * 0.12, color, alpha, glow * 0.6, 0.5);
  canvas.drawCapsule(cx + r * 0.35, cy - r * 0.05, cx, cy + r * 0.68, r * 0.48, r * 0.12, color, alpha, glow * 0.6, 0.5);
}

/**
 * Draw detailed anatomical lungs, trachea, bronchial tree, alveoli, and vagus nerve
 * inside a character's upper body.
 */
function drawDetailedPhysiology(canvas, joints, params) {
  const {
    scale = 1.0,
    facing = 1,
    lungFill = 0.2,      // 0..1 overall lung inflation
    alveoliPop = 0.0,    // 0..1 second-inhale alveolar recruitment flash
    vagusGlow = 0.0,     // 0..1 exhale parasympathetic vagal activation
    stressLevel = 0.0,   // 0..1 sympathetic red jagged stress
    calmLevel = 0.0,     // 0..1 golden coherence
    detailAlpha = 1.0,
    time = 0.0
  } = params;

  if (detailAlpha <= 0.01) return;

  const { head, neck, chest, pelvis, nose } = joints;

  // 1. Lung expansion geometry
  const expScale = 0.82 + 0.32 * lungFill;
  const lungW = 24 * scale * expScale;
  const lungH = 38 * scale * (0.85 + 0.28 * lungFill);

  // Lung color transitions from cool deep teal -> bright sky cyan on inhale -> warm golden-teal on exhale
  const baseLungCol = lerpColor([0.08, 0.42, 0.68], [0.22, 0.88, 1.35], Math.min(1, lungFill * 1.1));
  const lungCol = lerpColor(baseLungCol, [0.35, 1.15, 0.90], vagusGlow * 0.65);

  // Left and Right Lung Centers (in 3/4 view around chest center)
  const lCx = chest[0] - 15 * scale * expScale;
  const rCx = chest[0] + 15 * scale * expScale;
  const lCy = chest[1] - 4 * scale;

  // Draw Left & Right Lung Lobes (layered organic capsules)
  const lobeAlpha = (0.28 + 0.38 * lungFill) * detailAlpha;
  // Left lobe
  canvas.drawCapsule(
    lCx + 3 * scale, lCy - lungH * 0.48,
    lCx - 5 * scale, lCy + lungH * 0.45,
    lungW * 0.42, lungW * 0.68,
    lungCol, lobeAlpha, 14 * scale, 0.35
  );
  // Right lobe
  canvas.drawCapsule(
    rCx - 3 * scale, lCy - lungH * 0.48,
    rCx + 5 * scale, lCy + lungH * 0.45,
    lungW * 0.42, lungW * 0.68,
    lungCol, lobeAlpha, 14 * scale, 0.35
  );

  // Diaphragm arc underneath the lungs (moves down on inhale, domes up on exhale)
  const diaphY = lCy + lungH * 0.56 + (lungFill - 0.3) * 8 * scale;
  const diaphCol = lerpColor([0.20, 0.70, 0.95], [1.25, 0.92, 0.32], vagusGlow);
  const diaphPts = [];
  for (let i = 0; i <= 12; i++) {
    const u = i / 12;
    const dx = lerp(lCx - lungW * 0.62, rCx + lungW * 0.62, u);
    const arch = Math.sin(u * Math.PI) * (12 - 7 * lungFill) * scale;
    diaphPts.push([dx, diaphY - arch]);
  }
  canvas.drawPath(diaphPts, 2.2 * scale, diaphCol, 0.65 * detailAlpha, 8 * scale, 0.5);

  // 2. Nasal Passage, Pharynx & Trachea
  const carina = [chest[0], chest[1] - 12 * scale];
  const throat = [neck[0] + facing * 3 * scale, neck[1] - 2 * scale];
  const airwayCol = lerpColor([0.18, 0.72, 1.05], [0.55, 1.25, 1.50], lungFill);
  canvas.drawPath(
    [nose, [head[0] + facing * 4 * scale, head[1] + 8 * scale], throat, carina],
    (t) => (2.2 + t * 2.0) * scale,
    airwayCol,
    (0.45 + 0.45 * lungFill) * detailAlpha,
    8 * scale,
    0.5
  );

  // 3. Bronchial Tree & Alveolar Sacs
  const branches = [
    // Left bronchi
    { start: carina, mid: [lCx + 4 * scale, lCy - 8 * scale], tips: [
      [lCx - 8 * scale, lCy - 20 * scale],
      [lCx - 14 * scale, lCy - 6 * scale],
      [lCx - 16 * scale, lCy + 10 * scale],
      [lCx - 6 * scale, lCy + 18 * scale]
    ]},
    // Right bronchi
    { start: carina, mid: [rCx - 4 * scale, lCy - 8 * scale], tips: [
      [rCx + 8 * scale, lCy - 20 * scale],
      [rCx + 14 * scale, lCy - 6 * scale],
      [rCx + 16 * scale, lCy + 10 * scale],
      [rCx + 6 * scale, lCy + 18 * scale]
    ]}
  ];

  const bronchAlpha = (0.4 + 0.55 * lungFill) * detailAlpha;
  for (const b of branches) {
    canvas.drawCapsule(b.start[0], b.start[1], b.mid[0], b.mid[1], 3.2 * scale, 2.2 * scale, airwayCol, bronchAlpha, 6 * scale, 0.5);
    for (let i = 0; i < b.tips.length; i++) {
      const tip = b.tips[i];
      canvas.drawCapsule(b.mid[0], b.mid[1], tip[0], tip[1], 2.0 * scale, 1.1 * scale, airwayCol, bronchAlpha, 5 * scale, 0.5);

      // Alveolar cluster at each bronchiole tip (lights up dramatically during 2nd top-up inhale!)
      const alvR = (2.2 + 2.4 * lungFill + 2.8 * alveoliPop) * scale;
      const alvCol = lerpColor([0.25, 0.90, 1.30], [1.10, 1.65, 2.00], alveoliPop);
      const alvAlpha = (0.35 + 0.45 * lungFill + 0.5 * alveoliPop) * detailAlpha;
      canvas.drawCircle(tip[0], tip[1], alvR, alvCol, Math.min(1, alvAlpha), (6 + 14 * alveoliPop) * scale, 0.8, 0.7);
      // Sub-alveoli pearls
      if (alveoliPop > 0.05 || lungFill > 0.6) {
        const a1 = i * 1.3 + 0.5;
        const a2 = i * 1.3 + 2.4;
        const dSub = alvR * 1.05;
        canvas.drawCircle(tip[0] + Math.cos(a1) * dSub, tip[1] + Math.sin(a1) * dSub, alvR * 0.65, alvCol, Math.min(1, alvAlpha * 0.9), 8 * scale, 0.7, 0.8);
        canvas.drawCircle(tip[0] + Math.cos(a2) * dSub, tip[1] + Math.sin(a2) * dSub, alvR * 0.65, alvCol, Math.min(1, alvAlpha * 0.9), 8 * scale, 0.7, 0.8);
      }
    }
  }

  // 4. Brainstem & Vagus Nerve (Cranial Nerve X) connecting Brain -> Heart -> Diaphragm
  const brainPos = [head[0] - facing * 3 * scale, head[1] - 2 * scale];
  const heartPos = [chest[0] + 3 * scale, chest[1] + 5 * scale];
  const vagusCol = lerpColor([0.35, 0.75, 0.95], [1.65, 1.25, 0.35], Math.min(1, vagusGlow + calmLevel));
  const vagusAlpha = (0.30 + 0.70 * Math.max(vagusGlow, calmLevel * 0.7)) * detailAlpha;

  const vagusPath = [
    brainPos,
    [neck[0] - facing * 4 * scale, neck[1]],
    [chest[0] - facing * 5 * scale, chest[1] - 8 * scale],
    heartPos,
    [chest[0], diaphY - 4 * scale]
  ];
  canvas.drawPath(vagusPath, (2.0 + 1.8 * vagusGlow) * scale, vagusCol, vagusAlpha, (8 + 14 * vagusGlow) * scale, 0.8);

  // Neural glowing pulses traveling down the Vagus Nerve during exhale
  if (vagusGlow > 0.05) {
    for (let p = 0; p < 3; p++) {
      const u = ((time * 0.9 + p * 0.33) % 1.0);
      const seg = u * (vagusPath.length - 1);
      const idx = Math.min(vagusPath.length - 2, Math.floor(seg));
      const frac = seg - idx;
      const px = lerp(vagusPath[idx][0], vagusPath[idx + 1][0], frac);
      const py = lerp(vagusPath[idx][1], vagusPath[idx + 1][1], frac);
      canvas.drawCircle(px, py, 3.8 * scale, [1.9, 1.5, 0.55], vagusGlow * detailAlpha, 12 * scale, 0.9, 1.0);
    }
  }

  // Subtle brain neural crown glow
  canvas.drawCircle(brainPos[0], brainPos[1] - 4 * scale, 9 * scale, vagusCol, 0.35 * vagusAlpha, 12 * scale, 0.6, 0.7);
}

/**
 * Render an articulated human figure with expressive posture and inner heart/nervous system.
 */
function drawHumanFigure(canvas, pose, style) {
  const {
    x, y,                 // ground/hip reference or root
    scale = 1.0,
    facing = 1,           // +1 facing right, -1 facing left
    spineLean = 0.0,      // radians forward/backward lean
    crouch = 0.0,         // 0 = standing, 1 = kneeling/crouching warmly
    headTilt = 0.0,       // radians up/down head pitch
    armL = { shoulderAngle: 0.3, elbowAngle: 0.5 },
    armR = { shoulderAngle: -0.3, elbowAngle: -0.4 },
    stress = 0.0,         // 0..1 crimson stress state
    calm = 0.0,           // 0..1 golden calm/care state
    breath = 0.2,         // 0..1 chest expansion
    alveoliPop = 0.0,
    vagusGlow = 0.0,
    showAnatomy = 0.0,    // 0..1 internal lung/vagus detail visibility
    time = 0.0,
    alpha = 1.0
  } = { ...pose, ...style };

  if (alpha <= 0.01) return null;

  // Compute skeletal joint coordinates from posture parameters
  const crouchDrop = crouch * 44 * scale;
  const pelvis = [
    x - Math.sin(spineLean) * 8 * scale,
    y - (92 * scale - crouchDrop)
  ];

  const torsoLen = 68 * scale;
  const chest = [
    pelvis[0] + Math.sin(spineLean) * torsoLen * 0.68,
    pelvis[1] - Math.cos(spineLean) * torsoLen * 0.68
  ];
  const shoulderCenter = [
    pelvis[0] + Math.sin(spineLean) * torsoLen,
    pelvis[1] - Math.cos(spineLean) * torsoLen
  ];
  const neck = [
    shoulderCenter[0] + Math.sin(spineLean * 0.8) * 15 * scale,
    shoulderCenter[1] - Math.cos(spineLean * 0.8) * 15 * scale
  ];
  const headAngle = spineLean * 0.6 + headTilt;
  const head = [
    neck[0] + Math.sin(headAngle) * 18 * scale,
    neck[1] - Math.cos(headAngle) * 18 * scale
  ];
  const nose = [
    head[0] + facing * Math.cos(headAngle * 0.5) * 17.5 * scale,
    head[1] + Math.sin(headAngle * 0.5) * 4 * scale + 2 * scale
  ];
  const mouth = [
    head[0] + facing * Math.cos(headAngle * 0.5) * 15.5 * scale,
    head[1] + Math.sin(headAngle * 0.5) * 4 * scale + 9 * scale
  ];

  // Legs (standing vs kneeling/crouching smoothly)
  const footBack = [x - facing * (16 + crouch * 18) * scale, y];
  const footFront = [x + facing * (18 + crouch * 12) * scale, y];

  const kneeBack = [
    lerp(pelvis[0] - facing * 8 * scale, footBack[0] + facing * 18 * scale, 0.52) + facing * crouch * 18 * scale,
    lerp(pelvis[1], footBack[1], 0.52 + crouch * 0.34)
  ];
  const kneeFront = [
    lerp(pelvis[0] + facing * 8 * scale, footFront[0], 0.5) + facing * crouch * 24 * scale,
    lerp(pelvis[1], footFront[1], 0.5 - crouch * 0.08)
  ];

  // Arms (Back arm = armL, Front arm = armR)
  const upperArmLen = 40 * scale;
  const foreArmLen = 38 * scale;

  const shBack = [shoulderCenter[0] - facing * 8 * scale, shoulderCenter[1] + 4 * scale];
  const elBack = [
    shBack[0] + facing * Math.sin(armL.shoulderAngle) * upperArmLen,
    shBack[1] + Math.cos(armL.shoulderAngle) * upperArmLen
  ];
  const handBack = [
    elBack[0] + facing * Math.sin(armL.shoulderAngle + armL.elbowAngle) * foreArmLen,
    elBack[1] + Math.cos(armL.shoulderAngle + armL.elbowAngle) * foreArmLen
  ];

  const shFront = [shoulderCenter[0] + facing * 6 * scale, shoulderCenter[1] + 4 * scale];
  const elFront = [
    shFront[0] + facing * Math.sin(armR.shoulderAngle) * upperArmLen,
    shFront[1] + Math.cos(armR.shoulderAngle) * upperArmLen
  ];
  const handFront = [
    elFront[0] + facing * Math.sin(armR.shoulderAngle + armR.elbowAngle) * foreArmLen,
    elFront[1] + Math.cos(armR.shoulderAngle + armR.elbowAngle) * foreArmLen
  ];

  // Color palette based on emotional/physiological state
  // Neutral = deep celestial slate-blue; Stress = warm crimson-slate; Calm = luminous teal-gold
  const baseBody = lerpColor([0.14, 0.22, 0.36], [0.38, 0.12, 0.16], stress * 0.7);
  const bodyCol = lerpColor(baseBody, [0.16, 0.34, 0.42], calm * 0.8);
  const backLimbCol = [bodyCol[0] * 0.72, bodyCol[1] * 0.72, bodyCol[2] * 0.75];

  const baseRim = lerpColor([0.32, 0.58, 0.88], [1.45, 0.25, 0.22], stress);
  const rimCol = lerpColor(baseRim, [1.35, 0.98, 0.42], calm);

  const bodyAlpha = (0.88 - 0.16 * showAnatomy) * alpha;

  // --- 1. BACK LIMBS ---
  canvas.drawCapsule(pelvis[0] - facing * 5 * scale, pelvis[1], kneeBack[0], kneeBack[1], 13 * scale, 9.5 * scale, backLimbCol, bodyAlpha, 4 * scale);
  canvas.drawCapsule(kneeBack[0], kneeBack[1], footBack[0], footBack[1], 9.5 * scale, 6 * scale, backLimbCol, bodyAlpha, 4 * scale);
  canvas.drawCapsule(footBack[0], footBack[1], footBack[0] + facing * 12 * scale, footBack[1], 6 * scale, 4.5 * scale, backLimbCol, bodyAlpha);

  canvas.drawCapsule(shBack[0], shBack[1], elBack[0], elBack[1], 9.5 * scale, 7.5 * scale, backLimbCol, bodyAlpha, 5 * scale);
  canvas.drawCapsule(elBack[0], elBack[1], handBack[0], handBack[1], 7.5 * scale, 5.2 * scale, backLimbCol, bodyAlpha, 5 * scale);
  canvas.drawCircle(handBack[0], handBack[1], 6 * scale, rimCol, 0.55 * alpha, 8 * scale, 0.5, 0.4);

  // --- 2. TORSO, NECK & HEAD SILHOUETTE ---
  const chestExpand = (1.0 + 0.12 * breath) * scale;
  // Outer rim aura around torso
  canvas.drawCapsule(shoulderCenter[0], shoulderCenter[1], pelvis[0], pelvis[1], 24 * chestExpand, 16.5 * scale, rimCol, 0.35 * alpha, 14 * scale, 0.4);
  // Core torso silhouette
  canvas.drawCapsule(shoulderCenter[0], shoulderCenter[1], chest[0], chest[1], 22 * chestExpand, 20 * chestExpand, bodyCol, bodyAlpha, 6 * scale);
  canvas.drawCapsule(chest[0], chest[1], pelvis[0], pelvis[1], 20 * chestExpand, 15.5 * scale, bodyCol, bodyAlpha, 6 * scale);

  // Neck
  canvas.drawCapsule(shoulderCenter[0], shoulderCenter[1], head[0], head[1], 8.5 * scale, 7.5 * scale, bodyCol, bodyAlpha, 4 * scale);

  // Head (sculpted cranium + jaw + nose profile)
  canvas.drawCircle(head[0], head[1], 16.5 * scale, rimCol, 0.4 * alpha, 12 * scale, 0.5, 0.4);
  canvas.drawCircle(head[0], head[1], 15.5 * scale, bodyCol, Math.min(1, bodyAlpha + 0.08), 4 * scale);
  // Jaw / chin capsule
  const chin = [head[0] + facing * 8 * scale, head[1] + 12 * scale];
  canvas.drawCapsule(head[0] + facing * 2 * scale, head[1] + 2 * scale, chin[0], chin[1], 12 * scale, 7 * scale, bodyCol, Math.min(1, bodyAlpha + 0.08), 3 * scale);
  // Subtle nose bridge
  canvas.drawCapsule(head[0] + facing * 12 * scale, head[1] - 2 * scale, nose[0], nose[1], 4.5 * scale, 2.8 * scale, bodyCol, Math.min(1, bodyAlpha + 0.08), 2 * scale);

  // Expressive eye glow cue
  const eyePos = [head[0] + facing * 9.5 * scale, head[1] - 1.5 * scale];
  const eyeCol = lerpColor([0.65, 0.88, 1.2], [1.6, 1.3, 0.65], calm);
  canvas.drawCircle(eyePos[0], eyePos[1], 2.2 * scale, eyeCol, 0.75 * alpha, 5 * scale, 0.6, 0.6);

  // --- 3. INNER PHYSIOLOGY (Lungs, Bronchi, Alveoli, Vagus Nerve, Heart) ---
  const joints = { head, neck, chest, pelvis, nose, mouth, shoulderCenter, handFront, handBack };

  if (showAnatomy > 0.01) {
    drawDetailedPhysiology(canvas, joints, {
      scale,
      facing,
      lungFill: breath,
      alveoliPop,
      vagusGlow,
      stressLevel: stress,
      calmLevel: calm,
      detailAlpha: showAnatomy * alpha,
      time
    });
  }

  // Heart organ inside chest (always visible in all 3 characters!)
  const heartRateFreq = lerp(1.2, 3.4, stress);
  const beatPulse = 1.0 + (0.14 + 0.16 * stress) * Math.pow(Math.max(0, Math.sin(time * Math.PI * 2 * heartRateFreq)), 3);
  const heartR = 8.5 * scale * beatPulse;
  const heartBaseCol = lerpColor([0.35, 0.85, 1.25], [1.95, 0.18, 0.18], stress);
  const heartCol = lerpColor(heartBaseCol, [1.85, 1.28, 0.32], calm);
  const heartPos = [chest[0] + facing * 3 * scale, chest[1] + 4 * scale];

  drawHeartOrgan(canvas, heartPos[0], heartPos[1], heartR, heartCol, 0.92 * alpha, (14 + 10 * Math.max(stress, calm)) * scale);

  // Subtle neural/vascular lines connecting heart to brain and hands
  const nerveAlpha = (0.22 + 0.35 * Math.max(stress, calm)) * alpha;
  canvas.drawPath([head, neck, heartPos], 1.4 * scale, heartCol, nerveAlpha, 5 * scale, 0.6);
  canvas.drawPath([heartPos, shFront, elFront, handFront], 1.3 * scale, heartCol, nerveAlpha, 5 * scale, 0.6);

  // --- 4. FRONT LIMBS ---
  canvas.drawCapsule(pelvis[0] + facing * 5 * scale, pelvis[1], kneeFront[0], kneeFront[1], 13.5 * scale, 10 * scale, bodyCol, bodyAlpha, 5 * scale);
  canvas.drawCapsule(kneeFront[0], kneeFront[1], footFront[0], footFront[1], 10 * scale, 6.2 * scale, bodyCol, bodyAlpha, 5 * scale);
  canvas.drawCapsule(footFront[0], footFront[1], footFront[0] + facing * 13 * scale, footFront[1], 6.2 * scale, 4.8 * scale, bodyCol, bodyAlpha);

  // Front arm with subtle rim highlight
  canvas.drawCapsule(shFront[0], shFront[1], elFront[0], elFront[1], 10.5 * scale, 8.2 * scale, rimCol, 0.32 * alpha, 10 * scale, 0.4);
  canvas.drawCapsule(shFront[0], shFront[1], elFront[0], elFront[1], 9.8 * scale, 7.8 * scale, bodyCol, Math.min(1, bodyAlpha + 0.05), 4 * scale);

  canvas.drawCapsule(elFront[0], elFront[1], handFront[0], handFront[1], 8.2 * scale, 5.8 * scale, rimCol, 0.35 * alpha, 10 * scale, 0.4);
  canvas.drawCapsule(elFront[0], elFront[1], handFront[0], handFront[1], 7.8 * scale, 5.4 * scale, bodyCol, Math.min(1, bodyAlpha + 0.05), 4 * scale);
  canvas.drawCircle(handFront[0], handFront[1], 6.5 * scale, rimCol, 0.7 * alpha, 10 * scale, 0.6, 0.5);

  return { ...joints, heartPos };
}

module.exports = { drawHumanFigure, drawHeartOrgan, lerp, lerpColor };

'use strict';

const { drawHumanFigure, drawHeartOrgan, lerp, lerpColor } = require('./characters');
const { drawText } = require('./typography');

function clamp(x, a, b) {
  return Math.min(b, Math.max(a, x));
}

function smoothstep(edge0, edge1, x) {
  const t = clamp((x - edge0) / (edge1 - edge0 + 1e-9), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

// Deterministic pseudo-random helper
function hash(n) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453123;
  return s - Math.floor(s);
}

// Precompute background/global network nodes & edges
const NETWORK_NODES = [];
const NETWORK_EDGES = [];
(function initNetwork() {
  // Create 78 nodes distributed across a wide planetary dome
  for (let i = 0; i < 78; i++) {
    const layer = i % 3;
    const u = (i + 0.5) / 78;
    const angle = (u - 0.5) * 2.35; // spread across horizon arc
    const rad = 520 + layer * 135 + (hash(i * 7 + 1) - 0.5) * 85;
    const wx = 640 + Math.sin(angle) * rad * 1.35;
    const wy = 980 - Math.cos(angle) * rad * 0.82 + (hash(i * 13 + 3) - 0.5) * 55;
    NETWORK_NODES.push({
      wx, wy,
      distFromCenter: Math.hypot(wx - 620, wy - 420),
      size: 2.8 + hash(i * 19) * 2.6,
      phase: hash(i * 31) * Math.PI * 2
    });
  }
  // Connect nearby nodes into a web
  for (let i = 0; i < NETWORK_NODES.length; i++) {
    for (let j = i + 1; j < NETWORK_NODES.length; j++) {
      const d = Math.hypot(NETWORK_NODES[i].wx - NETWORK_NODES[j].wx, NETWORK_NODES[i].wy - NETWORK_NODES[j].wy);
      if (d < 175 && hash(i * 101 + j) > 0.25) {
        NETWORK_EDGES.push([i, j, d]);
      }
    }
  }
})();

/**
 * Draw a jagged crimson lightning/thorn bolt from (x0, y0) to (x1, y1)
 */
function drawJaggedBolt(canvas, x0, y0, x1, y1, progress, intensity, seed, scale = 1.0, shatter = 0.0) {
  if (intensity <= 0.01 || progress <= 0.01) return;

  const steps = 14;
  const maxStep = Math.max(1, Math.floor(steps * Math.min(1.0, progress)));
  const dx = x1 - x0;
  const dy = y1 - y0;
  const len = Math.hypot(dx, dy) + 1e-5;
  const nx = -dy / len;
  const ny = dx / len;

  const pts = [];
  for (let i = 0; i <= maxStep; i++) {
    const u = (i / steps) * Math.min(1.0, progress);
    const env = Math.sin(u * Math.PI);
    const jag = (hash(seed + i * 17.3) - 0.5) * 2.0 * 34 * scale * env;
    // If shattering (during exhale), shards drift upward and outward into golden embers
    const driftX = (hash(seed + i * 31.1) - 0.3) * 70 * shatter * scale;
    const driftY = -shatter * (45 + hash(seed + i * 47.7) * 85) * scale;
    pts.push([
      x0 + dx * u + nx * jag + driftX,
      y0 + dy * u + ny * jag + driftY
    ]);
  }

  const colCore = lerpColor([2.2, 0.22, 0.18], [1.9, 1.35, 0.38], shatter);
  const colGlow = lerpColor([1.6, 0.08, 0.12], [1.4, 0.95, 0.25], shatter);

  if (shatter < 0.35) {
    // Solid jagged lightning path
    canvas.drawPath(
      pts,
      (t) => (2.0 + Math.sin(t * Math.PI) * 4.5) * scale * (1.0 - shatter * 0.7),
      colCore,
      intensity,
      16 * scale,
      0.85
    );
    // Sharp side thorns
    for (let i = 2; i < pts.length - 1; i += 2) {
      const side = (i % 4 === 0 ? 1 : -1);
      const tx = pts[i][0] + (dx / len * 18 + nx * side * 20) * scale;
      const ty = pts[i][1] + (dy / len * 18 + ny * side * 20) * scale;
      canvas.drawCapsule(pts[i][0], pts[i][1], tx, ty, 3.2 * scale, 0.4 * scale, colCore, intensity * 0.85, 10 * scale, 0.8);
    }
  } else {
    // Shattering into floating golden-ember particles!
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i];
      const r = (4.5 - 2.8 * shatter) * scale;
      canvas.drawCircle(p[0], p[1], Math.max(1.2, r), colCore, intensity * (1.0 - shatter * 0.6), 14 * scale, 0.8, 0.9);
      // Secondary rising fireflies
      const fx = p[0] + Math.sin(shatter * 6 + i) * 18 * scale;
      const fy = p[1] - shatter * 32 * scale;
      canvas.drawCircle(fx, fy, 2.2 * scale, [1.8, 1.45, 0.45], intensity * (1.0 - shatter * 0.5), 10 * scale, 0.7, 1.0);
    }
  }
}

/**
 * Render the Act II Circular Breathing Pacer Halo & Airflow Streams
 */
function renderBreathingGuide(canvas, fig2, worldToScreen, camScale, t) {
  // Active between t = 2.75s and t = 7.45s
  const guideAlpha = smoothstep(2.75, 3.15, t) * (1.0 - smoothstep(7.10, 7.55, t));
  if (guideAlpha <= 0.01) return;

  const chestS = worldToScreen(fig2.chest[0], fig2.chest[1]);
  const noseS = worldToScreen(fig2.nose[0], fig2.nose[1]);
  const mouthS = worldToScreen(fig2.mouth[0], fig2.mouth[1]);

  const inhale1 = smoothstep(3.0, 4.15, t);         // 0 -> 1 during Inhale 1
  const inhale2 = smoothstep(4.20, 4.85, t);        // 0 -> 1 during Inhale 2 (Top-Up)
  const exhale = smoothstep(4.95, 7.25, t);         // 0 -> 1 during Long Slow Exhale

  const lungRatio = (0.80 * inhale1 + 0.20 * inhale2) * (1.0 - 0.85 * exhale);
  const ringR = (88 + 26 * lungRatio) * camScale;

  // Faint background reference track around the chest
  canvas.drawArc(chestS[0], chestS[1], ringR, 3.5, 0, Math.PI * 2, [0.18, 0.35, 0.52], 0.35 * guideAlpha, 6);

  // Segment 1: First Deep Inhale Arc (Top-Left: -0.92*PI to -0.18*PI)
  const a1Start = -0.92 * Math.PI;
  const a1End = lerp(a1Start, -0.18 * Math.PI, inhale1);
  if (inhale1 > 0.01) {
    const isAct1 = t >= 3.0 && t < 4.22 ? 1.0 : 0.45;
    canvas.drawArc(
      chestS[0], chestS[1], ringR, 7.5,
      a1Start, a1End,
      [0.25, 1.05, 1.65],
      guideAlpha * (0.65 + 0.35 * isAct1),
      14, 0.7
    );
  }

  // Segment 2: Second "Top-Up" Inhale Arc (Top-Right: -0.12*PI to +0.22*PI)
  const a2Start = -0.12 * Math.PI;
  const a2End = lerp(a2Start, 0.22 * Math.PI, inhale2);
  if (inhale2 > 0.01) {
    const isAct2 = t >= 4.18 && t < 4.95 ? 1.0 : 0.5;
    canvas.drawArc(
      chestS[0], chestS[1], ringR, 9.0,
      a2Start, a2End,
      [0.85, 1.65, 2.20],
      guideAlpha * (0.7 + 0.3 * isAct2),
      18, 0.85
    );
  }

  // Segment 3: Long Slow Exhale Sweep (Bottom: +0.28*PI to +1.02*PI)
  const a3Start = 0.28 * Math.PI;
  const a3End = lerp(a3Start, 1.02 * Math.PI, exhale);
  if (exhale > 0.01) {
    canvas.drawArc(
      chestS[0], chestS[1], ringR, 8.5,
      a3Start, a3End,
      [1.75, 1.25, 0.38],
      guideAlpha * 0.95,
      18, 0.85
    );
  }

  // --- Visual Callout Badges around the Breathing Ring ---
  // Badge 1: "1 · INHALE (80%)" (Upper Left)
  const b1Alpha = guideAlpha * smoothstep(2.9, 3.2, t) * (t < 4.25 ? 1.0 : 0.45);
  if (b1Alpha > 0.02) {
    const bx = chestS[0] - ringR * 1.18 - 48;
    const by = chestS[1] - ringR * 0.62;
    canvas.drawCircle(bx - 58, by + 7, 11, [0.22, 0.95, 1.55], b1Alpha, 10, 0.6, 0.5);
    drawText(canvas, '1', bx - 58, by + 1, 12, [1.5, 1.8, 2.0], b1Alpha, { align: 'center', weight: 0.14 });
    drawText(canvas, 'INHALE', bx - 38, by, 14, [0.45, 1.25, 1.75], b1Alpha, { align: 'left', weight: 0.11, glow: 6, additive: 0.5 });
  }

  // Badge 2: "+ 2 · TOP-UP (100%)" (Upper Right)
  const b2Alpha = guideAlpha * smoothstep(4.12, 4.30, t) * (t < 5.0 ? 1.0 : 0.45);
  if (b2Alpha > 0.02) {
    const bx = chestS[0] + ringR * 1.05 + 16;
    const by = chestS[1] - ringR * 0.62;
    canvas.drawCircle(bx + 12, by + 7, 11, [0.75, 1.55, 2.1], b2Alpha, 12, 0.7, 0.7);
    drawText(canvas, '+2', bx + 12, by + 1, 11, [1.8, 2.0, 2.2], b2Alpha, { align: 'center', weight: 0.13 });
    drawText(canvas, 'TOP-UP', bx + 32, by, 14, [0.95, 1.65, 2.15], b2Alpha, { align: 'left', weight: 0.11, glow: 8, additive: 0.6 });
  }

  // Badge 3: "3 · LONG SLOW EXHALE" (Below Chest Ring)
  const b3Alpha = guideAlpha * smoothstep(4.88, 5.15, t);
  if (b3Alpha > 0.02) {
    const bx = chestS[0];
    const by = chestS[1] + ringR + 22;
    drawText(canvas, '3 · LONG SLOW EXHALE', bx, by, 15, [1.85, 1.35, 0.42], b3Alpha, { align: 'center', weight: 0.11, glow: 10, additive: 0.6 });
  }

  // --- Animated Airflow Streams into Nose (Inhale 1 & 2) ---
  const inFlowAlpha = guideAlpha * (smoothstep(3.0, 3.2, t) * (1.0 - smoothstep(4.82, 5.02, t)));
  if (inFlowAlpha > 0.01) {
    const isSecondPuff = smoothstep(4.18, 4.32, t);
    const streamCount = isSecondPuff > 0.2 ? 2 : 1;
    for (let s = 0; s < streamCount; s++) {
      const pts = [];
      const col = s === 1 ? [0.95, 1.75, 2.2] : [0.28, 1.15, 1.75];
      for (let i = 0; i <= 16; i++) {
        const u = i / 16; // 0 = outside air, 1 = nose tip
        const dist = (1.0 - u) * (115 - s * 28) * camScale;
        const angle = -0.22 + s * 0.25 + Math.sin(u * 4.5 - t * 7.0) * 0.12 * (1.0 - u);
        pts.push([
          noseS[0] + Math.cos(angle) * dist,
          noseS[1] + Math.sin(angle) * dist
        ]);
      }
      canvas.drawPath(pts, (u) => (1.2 + u * 2.8) * (1.0 + 0.3 * isSecondPuff), col, inFlowAlpha * 0.85, 10, 0.8);

      // Moving air particles along the inhale stream
      for (let p = 0; p < 4; p++) {
        const pu = ((t * 2.4 + p * 0.25 + s * 0.13) % 1.0);
        const idx = Math.min(pts.length - 1, Math.floor(pu * pts.length));
        canvas.drawCircle(pts[idx][0], pts[idx][1], 3.5, col, inFlowAlpha, 9, 0.8, 0.9);
      }
    }
  }

  // --- Animated Golden-Teal Exhale Ribbon out of Mouth (t = 4.95s .. 7.3s) ---
  const exFlowAlpha = guideAlpha * smoothstep(4.92, 5.20, t) * (1.0 - smoothstep(7.05, 7.45, t));
  if (exFlowAlpha > 0.01) {
    const reach = smoothstep(4.95, 6.45, t);
    for (let rib = -1; rib <= 1; rib++) {
      const pts = [];
      for (let i = 0; i <= 22; i++) {
        const u = (i / 22) * reach;
        const dx = u * 270 * camScale;
        const wave = Math.sin(u * 6.5 - t * 4.2 + rib * 1.1) * (6 + u * 22) * camScale;
        pts.push([
          mouthS[0] + 6 + dx,
          mouthS[1] + rib * 6 + u * 18 * camScale + wave
        ]);
      }
      const col = rib === 0 ? [1.85, 1.38, 0.45] : [0.42, 1.35, 1.15];
      canvas.drawPath(
        pts,
        (u) => (1.5 + Math.sin(u * Math.PI) * 3.8) * (rib === 0 ? 1.2 : 0.85),
        col,
        exFlowAlpha * (rib === 0 ? 0.85 : 0.55),
        14, 0.85
      );
    }
  }
}

/**
 * Render the continuous Lower Autonomic Heart-Rate / Nervous System Waveform (ECG / HRV trace)
 */
function renderAutonomicWaveform(canvas, t) {
  const panelY = 626;
  const xStart = 180;
  const xEnd = 1100;
  const spanW = xEnd - xStart;

  // Transition states across the 10-second timeline
  const stressPhase = 1.0 - smoothstep(3.0, 5.4, t);
  const breathPhase = smoothstep(2.9, 3.4, t) * (1.0 - smoothstep(7.0, 7.6, t));
  const calmPhase = smoothstep(4.8, 6.2, t);
  const coRegPhase = smoothstep(7.3, 8.2, t); // 3 intertwined waves in Act III!

  // Subtle horizontal baseline
  canvas.drawCapsule(xStart, panelY, xEnd, panelY, 0.8, 0.8, [0.16, 0.26, 0.38], 0.45);

  const steps = 180;
  const ptsMain = [];
  const ptsSecond = [];
  const ptsThird = [];

  for (let i = 0; i <= steps; i++) {
    const u = i / steps;
    const x = xStart + u * spanW;

    // Spatial transition along the wave so at t=5..6s you see jagged red on the left morphing into smooth gold on the right!
    const localTime = t - (1.0 - u) * 1.6;
    const localCalm = smoothstep(4.2, 5.6, localTime);
    const localPause = smoothstep(2.7, 3.3, localTime) * (1.0 - localCalm);

    // 1. Chaotic high-frequency jagged sympathetic waveform (Act I)
    const phaseFast = u * 48 - t * 14.0;
    const qrs = Math.pow(Math.max(0, Math.sin(phaseFast)), 7) * 24
      - Math.pow(Math.max(0, Math.sin(phaseFast + 0.4)), 9) * 18
      + Math.sin(u * 95 - t * 22) * 7.5;

    // 2. Deep slow diaphragm expansion wave (Act II Inhale)
    const diaphragmWave = Math.sin(u * 10 - t * 3.2) * 14;

    // 3. Coherent, harmonious parasympathetic sine wave (Act II Exhale & Act III)
    const coherentWave = Math.sin(u * 14 - t * 3.6) * 12.5;

    const dy = qrs * (1.0 - localCalm) * (1.0 - localPause * 0.65)
      + diaphragmWave * localPause
      + coherentWave * localCalm;

    const env = Math.sin(u * Math.PI); // taper ends cleanly
    ptsMain.push([x, panelY - dy * env]);

    if (coRegPhase > 0.01) {
      const dy2 = Math.sin(u * 14 - t * 3.6 + 0.85) * 10.5 * env * coRegPhase;
      const dy3 = Math.sin(u * 14 - t * 3.6 - 0.85) * 10.5 * env * coRegPhase;
      ptsSecond.push([x, panelY - dy2]);
      ptsThird.push([x, panelY - dy3]);
    }
  }

  // Color of the waveform transitions from crimson -> cyan -> warm gold
  const col1 = lerpColor([1.95, 0.20, 0.20], [0.30, 1.15, 1.65], breathPhase);
  const mainCol = lerpColor(col1, [1.80, 1.28, 0.36], calmPhase);

  if (coRegPhase > 0.01) {
    canvas.drawPath(ptsSecond, 1.5, [0.35, 1.35, 1.25], 0.65 * coRegPhase, 8, 0.7);
    canvas.drawPath(ptsThird, 1.5, [1.55, 0.88, 0.35], 0.65 * coRegPhase, 8, 0.7);
  }
  canvas.drawPath(ptsMain, 2.2, mainCol, 0.9, 10, 0.75);

  // Leading pulse dot at right end of trace
  const lastPt = ptsMain[ptsMain.length - 1];
  canvas.drawCircle(lastPt[0], lastPt[1], 4.0, mainCol, 0.95, 12, 0.8, 0.9);
}

/**
 * Render a single frame of the 10-second animation at time `t` (in seconds, 0.0 <= t <= 10.0)
 */
function renderFrame(canvas, t) {
  const W = canvas.width;
  const H = canvas.height;

  // --- 1. TIMELINE ACT WEIGHTS & CAMERA CHOREOGRAPHY ---
  const act2Zoom = smoothstep(2.75, 3.45, t) * (1.0 - smoothstep(7.10, 7.85, t));
  const act3Wide = smoothstep(8.20, 9.65, t);

  // Camera zoom: 1.0 in Act I -> 1.42 in Act II (focused on Figure 2 & Child) -> 0.76 in late Act III (global reveal)
  const camScale = 1.0 + 0.42 * act2Zoom - 0.24 * act3Wide;
  const camFocusX = lerp(635, 675, act2Zoom);
  const camFocusY = lerp(375, 315, act2Zoom) + act3Wide * 25;

  function worldToScreen(wx, wy) {
    return [
      W * 0.5 + (wx - camFocusX) * camScale,
      H * 0.5 + (wy - camFocusY) * camScale
    ];
  }

  // --- 2. ATMOSPHERIC BACKGROUND ---
  const stressBg = smoothstep(0.2, 2.2, t) * (1.0 - smoothstep(3.2, 5.6, t));
  const calmBg = smoothstep(5.0, 7.8, t);

  const topRGB = lerpColor(
    lerpColor([0.015, 0.028, 0.065], [0.055, 0.015, 0.025], stressBg),
    [0.018, 0.045, 0.085],
    calmBg
  );
  const botRGB = lerpColor(
    lerpColor([0.035, 0.065, 0.135], [0.110, 0.022, 0.035], stressBg),
    [0.045, 0.115, 0.165],
    calmBg
  );
  const glowRGB = lerpColor(
    lerpColor([0.04, 0.08, 0.16], [0.24, 0.03, 0.04], stressBg),
    [0.24, 0.18, 0.06],
    calmBg
  );

  const centerS = worldToScreen(635, 350);
  canvas.drawBackground(topRGB, botRGB, glowRGB, centerS[0], centerS[1], 460 * camScale);

  // --- 3. PLANETARY HORIZON & HUMAN NETWORK CONSTELLATION ---
  // Curved Earth horizon arc beneath the characters (rises into full prominence in Act III)
  const groundY = 505;
  const earthCenter = worldToScreen(640, groundY + 1450);
  const earthRadius = 1450 * camScale;
  const horizonCol = lerpColor(
    lerpColor([0.12, 0.25, 0.45], [0.55, 0.12, 0.15], stressBg),
    [0.85, 0.68, 0.28],
    calmBg
  );
  canvas.drawArc(
    earthCenter[0], earthCenter[1],
    earthRadius, 2.5 + 3.0 * calmBg,
    -Math.PI * 0.72, -Math.PI * 0.28,
    horizonCol, 0.55 + 0.35 * calmBg, 18 * camScale, 0.6
  );

  // Ripple wave radius expanding from center in Act III (t = 7.2s .. 10.0s)
  const rippleProgress = smoothstep(7.15, 9.95, t);
  const rippleRadiusWorld = rippleProgress * 980;

  // Draw Network Edges
  const netBaseAlpha = 0.22 - 0.10 * act2Zoom + 0.48 * act3Wide;
  for (const [i, j] of NETWORK_EDGES) {
    const n1 = NETWORK_NODES[i];
    const n2 = NETWORK_NODES[j];
    const p1 = worldToScreen(n1.wx, n1.wy);
    const p2 = worldToScreen(n2.wx, n2.wy);

    const avgDist = 0.5 * (n1.distFromCenter + n2.distFromCenter);
    const lit = smoothstep(avgDist - 90, avgDist + 30, rippleRadiusWorld);
    const edgeCol = lerpColor(
      lerpColor([0.14, 0.26, 0.44], [0.48, 0.10, 0.12], stressBg),
      [1.25, 0.92, 0.32],
      lit
    );
    const edgeA = netBaseAlpha * (0.45 + 0.85 * lit);
    canvas.drawCapsule(p1[0], p1[1], p2[0], p2[1], 1.0, 1.0, edgeCol, edgeA, lit * 6, lit * 0.7);
  }

  // Draw Network Nodes (representing connected humanity across the world)
  for (let i = 0; i < NETWORK_NODES.length; i++) {
    const n = NETWORK_NODES[i];
    const p = worldToScreen(n.wx, n.wy);
    if (p[0] < -20 || p[0] > W + 20 || p[1] < -20 || p[1] > H + 20) continue;

    const lit = smoothstep(n.distFromCenter - 70, n.distFromCenter + 20, rippleRadiusWorld);
    const waveFront = Math.exp(-Math.pow((n.distFromCenter - rippleRadiusWorld) / 55, 2)) * smoothstep(7.2, 7.5, t);
    const nodeCol = lerpColor(
      lerpColor([0.22, 0.42, 0.68], [0.75, 0.15, 0.16], stressBg),
      [1.75, 1.32, 0.42],
      Math.min(1, lit + waveFront)
    );
    const r = (n.size + lit * 2.2 + waveFront * 3.5) * camScale;
    const nodeA = Math.min(1.0, netBaseAlpha * (0.7 + 1.1 * lit + waveFront));
    canvas.drawCircle(p[0], p[1], r, nodeCol, nodeA, (4 + 12 * (lit + waveFront)) * camScale, 0.7, 0.7);
  }

  // Expanding golden harmonic rings in Act III
  if (t > 7.2) {
    for (let k = 0; k < 3; k++) {
      const rt = clamp((t - 7.25 - k * 0.45) / 2.2, 0.0, 1.0);
      if (rt > 0.01 && rt < 0.99) {
        const ringCenter = worldToScreen(680, 390);
        const rad = rt * 720 * camScale;
        const a = (1.0 - rt) * 0.45;
        canvas.drawArc(ringCenter[0], ringCenter[1], rad, 3.0, 0, Math.PI * 2, [1.55, 1.18, 0.38], a, 16, 0.8);
      }
    }
  }

  // --- 4. THREE FOREGROUND HUMAN CHARACTERS (KINEMATICS & PHYSIOLOGY) ---

  // === FIGURE 1 (Left Adult: Receives external stress at t=0.3s, lashes out at t=1.2s, healed at t=7.7s) ===
  const f1Hit = smoothstep(0.25, 0.65, t);
  const f1Lunge = smoothstep(0.85, 1.35, t) * (1.0 - smoothstep(2.8, 3.6, t));
  const f1Heal = smoothstep(7.55, 8.35, t);
  const f1Stress = f1Hit * (1.0 - f1Heal);

  const fig1Screen = worldToScreen(275 + f1Lunge * 28, groundY);
  const fig1 = drawHumanFigure(canvas, {
    x: fig1Screen[0],
    y: fig1Screen[1],
    scale: 1.02 * camScale,
    facing: 1,
    spineLean: -0.10 * smoothstep(0.2, 0.5, t) * (1 - f1Lunge) + 0.28 * f1Lunge - 0.04 * f1Heal,
    crouch: 0.05 * f1Lunge,
    headTilt: 0.12 * f1Lunge - 0.06 * f1Heal,
    armL: {
      shoulderAngle: lerp(0.18, -0.55, f1Lunge),
      elbowAngle: lerp(0.35, -0.25, f1Lunge)
    },
    armR: {
      shoulderAngle: lerp(0.22, 1.25 * f1Lunge + 0.55 * f1Heal, 1.0),
      elbowAngle: lerp(0.40, 0.15 * (1 - f1Lunge) + 0.45 * f1Heal, 1.0)
    }
  }, {
    stress: f1Stress,
    calm: f1Heal,
    breath: 0.25 + 0.15 * Math.sin(t * 2.5),
    showAnatomy: 0.15,
    time: t,
    alpha: 1.0 - 0.35 * act2Zoom
  });

  // === FIGURE 2 (Center Protagonist: Struck at t=1.4s, Pauses at t=2.75s, Double Inhale + Slow Exhale t=3..7.2s, Kneels to care for Child t=7.3..10s) ===
  const f2Hit = smoothstep(1.30, 1.75, t);
  const f2Loom = smoothstep(1.75, 2.55, t) * (1.0 - smoothstep(2.70, 3.20, t));
  const f2Pause = smoothstep(2.70, 3.20, t);
  const inhale1 = smoothstep(3.00, 4.15, t);
  const inhale2 = smoothstep(4.20, 4.85, t);
  const exhale = smoothstep(4.95, 7.25, t);
  const f2Kneel = smoothstep(7.25, 8.15, t);

  const f2Breath = (0.18 + 0.62 * inhale1 + 0.20 * inhale2) * (1.0 - 0.72 * exhale) + 0.25 * f2Kneel;
  const f2AlveoliPop = smoothstep(4.18, 4.45, t) * (1.0 - smoothstep(5.15, 5.75, t));
  const f2VagusGlow = smoothstep(4.90, 5.35, t) * (1.0 - smoothstep(7.40, 8.20, t));
  const f2Calm = smoothstep(5.10, 6.80, t);
  const f2Stress = f2Hit * (1.0 - smoothstep(4.50, 5.85, t));

  // Posture transitions for Figure 2:
  // Looming forward in Act I -> Upright, centered & open-chested in Act II -> Kneeling warmly toward Child in Act III
  const f2WorldX = 610 + f2Loom * 26 + f2Kneel * 55;
  const fig2Screen = worldToScreen(f2WorldX, groundY);

  // Arms: raised aggressively in f2Loom -> hands resting gently near chest/diaphragm in Act II -> open warm embrace toward child in Act III
  const f2ArmRShoulder = f2Loom * 1.38 + f2Pause * (1 - f2Kneel) * 0.42 + f2Kneel * 1.12;
  const f2ArmRElbow = f2Loom * 0.20 + f2Pause * (1 - f2Kneel) * 0.85 + f2Kneel * 0.28;
  const f2ArmLShoulder = f2Loom * 0.85 + f2Pause * (1 - f2Kneel) * (-0.32) + f2Kneel * 0.92;
  const f2ArmLElbow = f2Loom * 0.30 + f2Pause * (1 - f2Kneel) * (-0.75) + f2Kneel * 0.35;

  const fig2 = drawHumanFigure(canvas, {
    x: fig2Screen[0],
    y: fig2Screen[1],
    scale: 1.06 * camScale,
    facing: 1,
    spineLean: 0.26 * f2Loom - 0.05 * (inhale1 + inhale2) * (1 - exhale) + 0.22 * f2Kneel,
    crouch: 0.78 * f2Kneel,
    headTilt: 0.16 * f2Loom - 0.10 * (inhale1 + inhale2) * (1 - exhale) + 0.18 * f2Kneel,
    armL: { shoulderAngle: f2ArmLShoulder, elbowAngle: f2ArmLElbow },
    armR: { shoulderAngle: f2ArmRShoulder, elbowAngle: f2ArmRElbow }
  }, {
    stress: f2Stress,
    calm: f2Calm,
    breath: clamp(f2Breath, 0.15, 1.0),
    alveoliPop: f2AlveoliPop,
    vagusGlow: f2VagusGlow,
    showAnatomy: 0.25 + 0.75 * smoothstep(2.6, 3.2, t) * (1.0 - smoothstep(7.2, 7.9, t)),
    time: t,
    alpha: 1.0
  });

  // === FIGURE 3 (Right Child: Cowers in fear at t=1.9..3.5s, watches in wonder t=4..7s, embraces warm light t=7.3..10s) ===
  const f3Fear = smoothstep(1.80, 2.45, t) * (1.0 - smoothstep(5.20, 6.60, t));
  const f3Relief = smoothstep(5.40, 7.20, t);
  const f3Connect = smoothstep(7.35, 8.25, t);

  const f3WorldX = 910 + f3Fear * 22 - f3Connect * 48;
  const fig3Screen = worldToScreen(f3WorldX, groundY);

  // Child raises hands to shield face when afraid, then opens arms forward to meet parent's hands in Act III
  const fig3 = drawHumanFigure(canvas, {
    x: fig3Screen[0],
    y: fig3Screen[1],
    scale: 0.68 * camScale,
    facing: -1, // facing left toward Figure 2
    spineLean: -0.28 * f3Fear + 0.12 * f3Connect,
    crouch: 0.38 * f3Fear,
    headTilt: 0.22 * f3Fear - 0.12 * f3Connect,
    armL: {
      shoulderAngle: lerp(0.25, 1.45, f3Fear) * (1 - f3Connect) + 0.95 * f3Connect,
      elbowAngle: lerp(0.35, 1.15, f3Fear) * (1 - f3Connect) + 0.25 * f3Connect
    },
    armR: {
      shoulderAngle: lerp(0.30, 1.60, f3Fear) * (1 - f3Connect) + 1.08 * f3Connect,
      elbowAngle: lerp(0.40, 1.25, f3Fear) * (1 - f3Connect) + 0.22 * f3Connect
    }
  }, {
    stress: f3Fear * 0.85,
    calm: f3Connect,
    breath: 0.25 + 0.15 * Math.sin(t * 3.0) + 0.2 * f3Relief,
    showAnatomy: 0.18,
    time: t,
    alpha: 1.0
  });

  // --- 5. ACT I & II: JAGGED CRIMSON CONTAGION BOLTS & THE STASIS PAUSE ---
  // Bolt 1: External world -> Figure 1 (t = 0.05s .. 1.15s)
  if (t < 1.35) {
    const p1 = smoothstep(0.05, 0.55, t);
    const fade1 = 1.0 - smoothstep(0.85, 1.30, t);
    const start1 = worldToScreen(40, 320);
    drawJaggedBolt(canvas, start1[0], start1[1], fig1.heartPos[0], fig1.heartPos[1], p1, fade1, 11.0, camScale);
  }

  // Bolt 2: Figure 1 -> Figure 2 (t = 1.00s .. 2.35s)
  if (t >= 0.95 && t < 2.65) {
    const p2 = smoothstep(1.00, 1.55, t);
    const fade2 = 1.0 - smoothstep(1.95, 2.55, t);
    drawJaggedBolt(canvas, fig1.handFront[0], fig1.handFront[1], fig2.heartPos[0], fig2.heartPos[1], p2, fade2, 29.0, camScale);
  }

  // Bolt 3: Figure 2 -> Child (Errupts at t = 1.95s, freezes in Stasis Shield at t = 2.75s, shatters into golden fireflies during Exhale t = 5.1s .. 6.8s!)
  if (t >= 1.90 && t < 7.05) {
    const p3 = clamp(smoothstep(1.95, 2.75, t) * 0.86, 0.0, 0.86); // Freezes at 86% (just in front of the child!)
    const shatter = smoothstep(5.15, 6.75, t);
    const fade3 = 1.0 - smoothstep(6.45, 7.00, t);
    const targetX = lerp(fig2.handFront[0], fig3.head[0] - 22 * camScale, 0.88);
    const targetY = lerp(fig2.handFront[1], fig3.chest[1], 0.88);

    drawJaggedBolt(canvas, fig2.handFront[0], fig2.handFront[1], targetX, targetY, p3 / 0.86, fade3, 53.0, camScale, shatter);

    // Stasis Barrier around the frozen tip of Bolt 3 (t = 2.68s .. 6.2s)
    const shieldAlpha = smoothstep(2.68, 2.95, t) * (1.0 - smoothstep(5.45, 6.25, t));
    if (shieldAlpha > 0.01) {
      const shR = (34 + 4 * Math.sin(t * 6.0)) * camScale;
      canvas.drawCircle(targetX, targetY, shR, [0.18, 0.85, 1.35], shieldAlpha * 0.22, 18 * camScale, 0.7, 0.6);
      canvas.drawArc(targetX, targetY, shR, 3.2 * camScale, 0, Math.PI * 2, [0.45, 1.35, 1.85], shieldAlpha * 0.85, 12 * camScale, 0.8);
    }
  }

  // --- 6. ACT II: BREATHING PACER HALO & AIRFLOW ---
  renderBreathingGuide(canvas, fig2, worldToScreen, camScale, t);

  // --- 7. ACT III: THE GOLDEN ORB OF CARE & CO-REGULATION BRIDGE ---
  if (t >= 7.15) {
    const careAlpha = smoothstep(7.20, 7.85, t);
    const orbX = 0.5 * (fig2.handFront[0] + fig3.handFront[0]);
    const orbY = 0.5 * (fig2.handFront[1] + fig3.handFront[1]);
    const orbR = (14 + 4 * Math.sin(t * 4.0)) * camScale * careAlpha;

    // Warm golden sphere of care held between parent and child
    canvas.drawCircle(orbX, orbY, orbR, [2.1, 1.55, 0.50], careAlpha * 0.95, 28 * camScale, 0.9, 0.9);
    drawHeartOrgan(canvas, orbX, orbY, orbR * 0.55, [2.4, 1.9, 0.85], careAlpha, 14 * camScale);

    // Luminous golden-teal co-regulation streams linking Heart 1 <-> Heart 2 <-> Heart 3
    const bridgePts23 = [];
    for (let i = 0; i <= 16; i++) {
      const u = i / 16;
      const bx = lerp(fig2.heartPos[0], fig3.heartPos[0], u);
      const by = lerp(fig2.heartPos[1], fig3.heartPos[1], u) - Math.sin(u * Math.PI) * 18 * camScale;
      bridgePts23.push([bx, by]);
    }
    canvas.drawPath(bridgePts23, 3.2 * camScale, [1.95, 1.42, 0.45], careAlpha * 0.85, 14 * camScale, 0.85);

    const heal1Alpha = smoothstep(7.45, 8.20, t);
    if (heal1Alpha > 0.01) {
      const bridgePts12 = [];
      for (let i = 0; i <= 20; i++) {
        const u = i / 20;
        const bx = lerp(fig2.heartPos[0], fig1.heartPos[0], u);
        const by = lerp(fig2.heartPos[1], fig1.heartPos[1], u) - Math.sin(u * Math.PI) * 28 * camScale;
        bridgePts12.push([bx, by]);
      }
      canvas.drawPath(bridgePts12, 2.8 * camScale, [1.75, 1.28, 0.42], heal1Alpha * 0.78, 12 * camScale, 0.8);
    }
  }

  // --- 8. CONTINUOUS LOWER AUTONOMIC WAVEFORM HUD ---
  renderAutonomicWaveform(canvas, t);

  // --- 9. SUBTLE, HIGH-CRAFT APHORISTIC CAPTIONS ---
  // Act I Caption (0.15s .. 2.75s)
  const cap1Alpha = smoothstep(0.15, 0.55, t) * (1.0 - smoothstep(2.45, 2.85, t));
  if (cap1Alpha > 0.01) {
    drawText(canvas, 'PAIN NOT TRANSFORMED IS TRANSMITTED', W * 0.5, 668, 17, [1.55, 0.55, 0.55], cap1Alpha, {
      align: 'center', tracking: 0.20, weight: 0.10, glow: 8, additive: 0.4
    });
  }

  // Act II Caption (2.85s .. 7.25s)
  const cap2Alpha = smoothstep(2.85, 3.25, t) * (1.0 - smoothstep(6.95, 7.35, t));
  if (cap2Alpha > 0.01) {
    drawText(canvas, 'PAUSE · DOUBLE INHALE · LONG SLOW EXHALE', W * 0.5, 668, 17, [0.55, 1.35, 1.75], cap2Alpha, {
      align: 'center', tracking: 0.19, weight: 0.10, glow: 8, additive: 0.5
    });
  }

  // Act III Caption (7.30s .. 10.0s)
  const cap3Alpha = smoothstep(7.30, 7.75, t);
  if (cap3Alpha > 0.01) {
    drawText(canvas, 'ONE BREATH BREAKS THE CHAIN · PASS ON CARE', W * 0.5, 668, 17, [1.75, 1.32, 0.48], cap3Alpha, {
      align: 'center', tracking: 0.19, weight: 0.10, glow: 10, additive: 0.5
    });
  }
}

