const t0 = Date.now();

for (let i = 0; i < times.length; i++) {
  const t = times[i];
  renderFrame(canvas, t);
  const rgb = canvas.toSRGB();
  const header = Buffer.from(`P6\n${W} ${H}\n255\n`, 'ascii');
  const ppmPath = `tmp_preview/frame_${i}.ppm`;
  const jpgPath = `tmp_preview/frame_${i}.jpg`;
  fs.writeFileSync(ppmPath, Buffer.concat([header, Buffer.from(rgb.buffer, rgb.byteOffset, rgb.byteLength)]));
  execSync(`ffmpeg -y -loglevel error -i ${ppmPath} -q:v 2 ${jpgPath}`);
}

// Combine into a 2x2 contact sheet jpg for efficient inspection
execSync(`ffmpeg -y -loglevel error -i tmp_preview/frame_0.jpg -i tmp_preview/frame_1.jpg -i tmp_preview/frame_2.jpg -i tmp_preview/frame_3.jpg -filter_complex "[0:v][1:v]hstack=inputs=2[top];[2:v][3:v]hstack=inputs=2[bot];[top][bot]vstack=inputs=2,scale=1600:900" -q:v 2 tmp_preview/contact_sheet.jpg`);

console.log(`Rendered 4 frames in ${Date.now() - t0} ms`);

